import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Interview } from '../../types/interview.types';
import { Dialog, DialogContent, DialogHeader, DialogTitle } from '@/components/ui/dialog';
import { Input } from '@/components/ui/input';
import { useEffect, useState } from 'react';
import EyeIcon from '@/components/icons/marketing/EyeIcon';
import { apiPost } from '@/lib/axios/axios-utils';
import { endpoints } from '@/lib/axios/axios-global';
import { toast } from 'sonner';
import { formatDatetimeLocalForApi } from '../careerList/utils';

function toDatetimeLocalValue(iso?: string | null): string {
    if (!iso) return '';
    const d = new Date(iso);
    if (Number.isNaN(d.getTime())) return '';
    const pad = (n: number) => String(n).padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

interface InterviewPreviewProps {
    interview: Interview | null;
    openUpdateDialog: boolean;
    setopenUpdateDialog: (open: boolean) => void;
    onUpdated?: () => void;
}

export default function InterviewPreview({
    interview,
    openUpdateDialog,
    setopenUpdateDialog,
    onUpdated,
}: InterviewPreviewProps) {
    const [status, setStatus] = useState('');
    const [notes, setNotes] = useState('');
    const [scheduledAt, setScheduledAt] = useState('');
    const [saving, setSaving] = useState(false);

    useEffect(() => {
        if (!openUpdateDialog || !interview) return;
        setStatus(interview.status ?? '');
        setNotes(interview.notes ?? '');
        setScheduledAt(toDatetimeLocalValue(interview.scheduled_at));
    }, [openUpdateDialog, interview?.id, interview?.status, interview?.notes, interview?.scheduled_at]);

    const handleSave = async () => {
        if (!interview?.id) {
            toast.error('معرّف المقابلة غير متوفر');
            return;
        }
        setSaving(true);
        try {
            const scheduledApi = scheduledAt.trim()
                ? formatDatetimeLocalForApi(scheduledAt)
                : undefined;
            await apiPost({
                endpoint: `${endpoints.interview.update}${interview.id}`,
                body: {
                    status: status.trim() || null,
                    notes: notes.trim() || null,
                    scheduled_at: scheduledApi ?? null,
                },
            });
            toast.success('تم تحديث المقابلة');
            setopenUpdateDialog(false);
            onUpdated?.();
        } catch (e: unknown) {
            let msg = 'تعذر حفظ التعديلات';
            if (e && typeof e === 'object' && 'response' in e) {
                const ax = e as { response?: { data?: { msg?: string } } };
                msg = ax.response?.data?.msg || msg;
            }
            toast.error(msg);
        } finally {
            setSaving(false);
        }
    };

    const applicantName = interview?.applicant?.name ?? interview?.name ?? '';
    const jobTitle = interview?.applicant?.job?.title ?? interview?.description ?? '';
    const level = interview?.applicant?.level ?? '';
    const workType = interview?.applicant?.work_type ?? '';

    return (
        <div>
            <Dialog open={openUpdateDialog} onOpenChange={setopenUpdateDialog}>
                <DialogContent
                    dir="rtl"
                    showCloseButton={false}
                    className="max-w-[520px] rounded-xl border border-[#E8E7EA] bg-white-blue-50 p-5 sm:p-6"
                >
                    <DialogHeader className="space-y-2">
                        <DialogTitle className="text-right text-[20px] font-semibold text-[#205295]">
                            <div className="flex items-center gap-2">
                                <EyeIcon width="24" height="24" />
                                تعديل المقابلة
                            </div>
                        </DialogTitle>
                        <div className="w-full border-b border-[#E8E7EA]" />
                    </DialogHeader>

                    <div className="mt-2 grid grid-cols-1 gap-3 sm:grid-cols-2">
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">اسم المتقدم</label>
                            <Input value={applicantName} readOnly className="h-9 bg-[#F9FAFB]" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">الوظيفة</label>
                            <Input value={jobTitle} readOnly className="h-9 bg-[#F9FAFB]" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">المستوى</label>
                            <Input value={level} readOnly className="h-9 bg-[#F9FAFB]" />
                        </div>
                        <div className="space-y-1.5">
                            <label className="text-xs text-[#625E74]">نوع العمل</label>
                            <Input value={workType} readOnly className="h-9 bg-[#F9FAFB]" />
                        </div>
                        <div className="space-y-1.5 sm:col-span-2">
                            <label className="text-xs text-[#625E74]">موعد المقابلة</label>
                            <Input
                                type="datetime-local"
                                value={scheduledAt}
                                onChange={(e) => setScheduledAt(e.target.value)}
                                className="h-9 bg-white"
                            />
                        </div>
                        <div className="space-y-1.5 sm:col-span-2">
                            <label className="text-xs text-[#625E74]">الحالة</label>
                            <Input
                                value={status}
                                onChange={(e) => setStatus(e.target.value)}
                                placeholder="مثال: scheduled، accepted، rejected"
                                className="h-9 bg-white"
                            />
                        </div>
                        <div className="space-y-1.5 sm:col-span-2">
                            <label className="text-xs text-[#625E74]">ملاحظات</label>
                            <textarea
                                value={notes}
                                onChange={(e) => setNotes(e.target.value)}
                                rows={4}
                                className="w-full resize-y rounded-md border border-[#E5E7EB] bg-white p-2 text-sm text-[#625E74] outline-none"
                                placeholder="ملاحظات المقابلة..."
                            />
                        </div>
                    </div>

                    <div className="mt-5 flex flex-wrap justify-end gap-2">
                        <PrimaryButton
                            type="button"
                            variant="outline"
                            onClick={() => setopenUpdateDialog(false)}
                            className="h-9 min-w-[100px] border border-[#D0D5DD] bg-transparent text-[#625E74]"
                        >
                            إلغاء
                        </PrimaryButton>
                        <PrimaryButton
                            type="button"
                            disabled={saving}
                            onClick={() => void handleSave()}
                            className="h-9 min-w-[120px]"
                        >
                            {saving ? 'جاري الحفظ...' : 'حفظ'}
                        </PrimaryButton>
                    </div>
                </DialogContent>
            </Dialog>
        </div>
    );
}
